// @FIGURE_CODE_BEGIN
const container = document.getElementById('container');
const canvas = document.createElement('canvas');
canvas.style.width = '100%';
canvas.style.height = '100%';
canvas.style.display = 'block';
container.appendChild(canvas);

let currentDistance = 200;
const getRegion = (d) => d < 60 ? 'close' : (d <= 100 ? 'bond' : 'far');

// Helper to draw the 3D-looking green hydrogen spheres
function drawSphere(ctx, x, y, r) {
    const grad = ctx.createRadialGradient(x - r*0.3, y - r*0.3, r*0.1, x, y, r);
    grad.addColorStop(0, '#75c87b');
    grad.addColorStop(0.8, '#1e7b2f');
    grad.addColorStop(1, '#0c4d18');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, 2*Math.PI);
    ctx.fill();
    ctx.lineWidth = 1;
    ctx.strokeStyle = '#0a3610';
    ctx.stroke();
}

// Helper for the background static states (ghost atoms + labels)
function drawStaticGroup(ctx, xAxis, yAxis, px, py, text, color, align, myRegion, customVd) {
    const isActive = getRegion(currentDistance) === myRegion;
    ctx.globalAlpha = isActive ? 1.0 : 0.25;
    const R = 11;

    ctx.fillStyle = color;
    ctx.font = '13px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = align;
    const textY = align === 'bottom' ? py - R - 6 : py + R + 6;
    ctx.fillText(text, px, textY);

    drawSphere(ctx, px - customVd/2, py, R);
    drawSphere(ctx, px + customVd/2, py, R);

    ctx.globalAlpha = 1.0;
}

// Generate the Morse potential energy curve data points
const energyData = [];
for(let r = 30; r <= 200; r += 1) {
    // Shifted Morse potential to match the chart scale requirements
    let e = 4.5 * Math.pow(1 - Math.exp(-0.035 * (r - 74)), 2) - 4.5;
    energyData.push({ x: r, y: e });
}

// Custom drawing plugin to build the scene pixel-perfectly without default axes getting in the way
const customPlugin = {
    id: 'customAnnotations',
    beforeDraw: (chart) => {
        const ctx = chart.ctx;
        const chartArea = chart.chartArea;
        const xAxis = chart.scales.x;
        const yAxis = chart.scales.y;

        // 1. Pale blue background
        ctx.fillStyle = '#eaf4f8';
        ctx.fillRect(chartArea.left, chartArea.top, chartArea.width, chartArea.height);

        // 2. Y-axis Gradient Arrow (Energy)
        const arrowX = chartArea.left - 45;
        const arrowBottom = chartArea.bottom;
        const arrowTop = chartArea.top;

        const gradArrow = ctx.createLinearGradient(0, arrowBottom, 0, arrowTop);
        gradArrow.addColorStop(0, '#fef0d2'); // cream
        gradArrow.addColorStop(1, '#ed6a48'); // orange

        ctx.fillStyle = gradArrow;
        ctx.beginPath();
        ctx.moveTo(arrowX - 8, arrowBottom);
        ctx.lineTo(arrowX + 8, arrowBottom);
        ctx.lineTo(arrowX + 8, arrowTop + 20);
        ctx.lineTo(arrowX + 16, arrowTop + 20);
        ctx.lineTo(arrowX, arrowTop);
        ctx.lineTo(arrowX - 16, arrowTop + 20);
        ctx.lineTo(arrowX - 8, arrowTop + 20);
        ctx.closePath();
        ctx.fill();
        ctx.strokeStyle = '#444';
        ctx.lineWidth = 1;
        ctx.stroke();

        ctx.save();
        ctx.translate(arrowX, (arrowTop + arrowBottom) / 2);
        ctx.rotate(-Math.PI / 2);
        ctx.fillStyle = '#000';
        ctx.font = 'bold 13px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('Energy', 0, 0);
        ctx.restore();

        // 3. Y-axis horizontal zero line and tick marks (+, 0, -)
        const yZero = yAxis.getPixelForValue(0);
        ctx.beginPath();
        ctx.setLineDash([5, 5]);
        ctx.moveTo(chartArea.left, yZero);
        ctx.lineTo(chartArea.right, yZero);
        ctx.strokeStyle = '#666';
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.fillStyle = '#000';
        ctx.font = '16px sans-serif';
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        ctx.fillText('+', chartArea.left - 10, yAxis.getPixelForValue(7.5));
        ctx.fillText('0', chartArea.left - 10, yZero);
        ctx.fillText('–', chartArea.left - 10, yAxis.getPixelForValue(-3));

        // 4. X-axis Arrow and label (Internuclear distance)
        const xCenter = (chartArea.left + chartArea.right) / 2;
        const xTextY = chartArea.bottom + 35;

        ctx.fillStyle = '#000';
        ctx.font = '14px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('Internuclear distance', xCenter - 30, xTextY);

        const textWidth = ctx.measureText('Internuclear distance').width;
        const magArrowX = xCenter - 30 + textWidth/2 + 10;

        ctx.fillStyle = '#d31f7c'; // magenta
        ctx.beginPath();
        ctx.moveTo(magArrowX, xTextY - 2);
        ctx.lineTo(magArrowX + 30, xTextY - 2);
        ctx.lineTo(magArrowX + 30, xTextY - 6);
        ctx.lineTo(magArrowX + 40, xTextY);
        ctx.lineTo(magArrowX + 30, xTextY + 6);
        ctx.lineTo(magArrowX + 30, xTextY + 2);
        ctx.lineTo(magArrowX, xTextY + 2);
        ctx.closePath();
        ctx.fill();
    },
    afterDraw: (chart) => {
        const ctx = chart.ctx;
        const xAxis = chart.scales.x;
        const yAxis = chart.scales.y;
        const chartArea = chart.chartArea;

        // 1. Bond length minimum dashed line and annotation (74 pm)
        const minPx = xAxis.getPixelForValue(74);
        const minY = yAxis.getPixelForValue(-4.5);
        const bottomY = chartArea.bottom - 20;

        ctx.beginPath();
        ctx.setLineDash([4, 4]);
        ctx.moveTo(minPx, minY);
        ctx.lineTo(minPx, bottomY + 15);
        ctx.strokeStyle = '#555';
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.fillStyle = '#278e58';
        ctx.font = '14px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        ctx.fillText('74 pm', minPx, bottomY + 20);

        const arrowEndX = minPx + 15;
        const arrowStartX = minPx + 60;
        const arrowY = bottomY + 5;

        ctx.beginPath();
        ctx.moveTo(arrowStartX, arrowY);
        ctx.lineTo(arrowEndX, arrowY);
        ctx.lineTo(arrowEndX + 5, arrowY - 3);
        ctx.moveTo(arrowEndX, arrowY);
        ctx.lineTo(arrowEndX + 5, arrowY + 3);
        ctx.strokeStyle = '#278e58';
        ctx.lineWidth = 1;
        ctx.stroke();

        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText('Bond length', arrowStartX + 5, arrowY);

        // 2. Static Groups (Ghosts)
        drawStaticGroup(ctx, xAxis, yAxis, xAxis.getPixelForValue(45), chartArea.top + 35, 'HH (too close)', '#378b8e', 'bottom', 'close', 10);
        drawStaticGroup(ctx, xAxis, yAxis, xAxis.getPixelForValue(74), yAxis.getPixelForValue(-1.5), 'H—H', '#278e58', 'top', 'bond', 22);
        drawStaticGroup(ctx, xAxis, yAxis, xAxis.getPixelForValue(145), yAxis.getPixelForValue(2), 'H - - - H (too far)', '#c5337b', 'bottom', 'far', 40);

        // 3. Dynamic Locators (Dot on curve & floating Atoms tracking the slider)
        const curPx = xAxis.getPixelForValue(currentDistance);
        const curEnergy = 4.5 * Math.pow(1 - Math.exp(-0.035 * (currentDistance - 74)), 2) - 4.5;
        const curPy = yAxis.getPixelForValue(curEnergy);

        // Pink dot on the curve
        ctx.fillStyle = '#d31f7c';
        ctx.beginPath();
        ctx.arc(curPx, curPy, 6, 0, 2*Math.PI);
        ctx.fill();
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.5;
        ctx.stroke();

        // Spheres tracking distance proportionally above the curve point
        const R = 11;
        const curVd = (currentDistance / 74) * 22;
        const dynamicSpheresY = curPy - 45;
        // Keep them from clipping off the top or bleeding into the X axis text
        const clampedY = Math.max(chartArea.top + 20, Math.min(chartArea.bottom - 40, dynamicSpheresY));

        drawSphere(ctx, curPx - curVd/2, clampedY, R);
        drawSphere(ctx, curPx + curVd/2, clampedY, R);
    }
};

window.myChart = new Chart(canvas, {
    type: 'line',
