Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<div style="margin-bottom:12px; padding-bottom:12px; border-bottom:1px solid #dcdfe3;">
    <p id="demoNarration" style="margin:0 0 10px 0;font-size:11.5px;line-height:1.45;"></p>
    <div style="display:flex;align-items:center;justify-content:center;gap:10px;">
        <button onclick="prevStep()" id="btnPrev">◀</button>
        <span id="stepLabel" style="font-weight:600;font-size:12px;min-width:30px;text-align:center;"></span>
        <button onclick="nextStep()" id="btnNext">▶</button>
    </div>
</div>
<label>Internuclear distance (pm): <output id="distanceVal">200</output>
    <input id="distanceInput" type="range" min="30" max="200" step="1" value="200" oninput="document.getElementById('distanceVal').value=this.value;update_distance(+this.value)">
</label>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
const container = document.getElementById('container');
const canvas = document.createElement('canvas');
canvas.style.width = '100%';
canvas.style.height = '100%';
canvas.style.display = 'block';
container.appendChild(canvas);

let currentDistance = 200;

function drawSphere(ctx, x, y, r) {
    // Flat solid dark green fill as requested
    ctx.fillStyle = '#147a3f'; 
    ctx.beginPath();
    ctx.arc(x, y, r, 0, 2*Math.PI);
    ctx.fill();
    ctx.lineWidth = 1;
    ctx.strokeStyle = '#0c4d26'; // Darker stroke for definition
    ctx.stroke();
}

const energyData = [];
for(let r = 30; r <= 200; r += 1) {
    let e = 4.5 * Math.pow(1 - Math.exp(-0.035 * (r - 74)), 2) - 4.5;
    energyData.push({ x: r, y: e });
}

const customPlugin = {
    id: 'customAnnotations',
    beforeDraw: (chart) => {
        const ctx = chart.ctx;
        const chartArea = chart.chartArea;
        const yAxis = chart.scales.y;

        // 1. Pale blue background field
        ctx.fillStyle = '#eaf4f8';
        ctx.fillRect(chartArea.left, chartArea.top, chartArea.width, chartArea.height);

        // 2. Y-axis Thick Gradient Arrow (Energy)
        const arrowX = 30; // Positioned safely to the left of chart area
        const arrowBottom = chartArea.bottom;
        const arrowTop = chartArea.top;

        const arrowW = 20;
        const headW = 34;
        const headH = 18;

        const gradArrow = ctx.createLinearGradient(0, arrowBottom, 0, arrowTop);
        gradArrow.addColorStop(0, '#fbf2d8'); 
        gradArrow.addColorStop(0.5, '#f4a582'); 
        gradArrow.addColorStop(1, '#e25845'); 

        ctx.fillStyle = gradArrow;
        ctx.beginPath();
        ctx.moveTo(arrowX - arrowW/2, arrowBottom);
        ctx.lineTo(arrowX + arrowW/2, arrowBottom);
        ctx.lineTo(arrowX + arrowW/2, arrowTop + headH);
        ctx.lineTo(arrowX + headW/2, arrowTop + headH);
        ctx.lineTo(arrowX, arrowTop);
        ctx.lineTo(arrowX - headW/2, arrowTop + headH);
        ctx.lineTo(arrowX - arrowW/2, arrowTop + headH);
        ctx.closePath();
        ctx.fill();
        ctx.strokeStyle = '#444';
        ctx.lineWidth = 1;
        ctx.stroke();

        ctx.save();
        ctx.translate(arrowX, (arrowTop + arrowBottom) / 2);
        ctx.rotate(-Math.PI / 2);
        ctx.fillStyle = '#000';
        ctx.font = 'bold 14px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('Energy', 0, 0);
        ctx.restore();

        // 3. Y-axis horizontal zero line and tick marks (+, 0, -)
        const yZero = yAxis.getPixelForValue(0);
        ctx.beginPath();
        ctx.setLineDash([5, 5]);
        ctx.moveTo(chartArea.left, yZero);
        ctx.lineTo(chartArea.right, yZero);
        ctx.strokeStyle = '#888';
        ctx.stroke();
        ctx.setLineDash([]);

        // Tick labels placed neatly between the energy arrow and the chart boundary
        ctx.fillStyle = '#000';
        ctx.font = '16px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('+', 58, yAxis.getPixelForValue(10));
        ctx.fillText('0', 58, yZero);
        ctx.fillText('–', 58, yAxis.getPixelForValue(-4));

        // 4. X-axis Arrow and label (Internuclear distance) centered properly below text
        const xCenter = (chartArea.left + chartArea.right) / 2;
        const xTextY = chartArea.bottom + 25;
        const xText = 'Internuclear distance';

        ctx.fillStyle = '#000';
        ctx.font = '14px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        ctx.fillText(xText, xCenter, xTextY);

        const axW = 60;
        const axH = 4;
        const aHeadW = 12;
        const aHeadH = 14;
        const arrowCy = chartArea.bottom + 48; // Positioned vertically below the label

        ctx.fillStyle = '#d31f7c'; 
        ctx.beginPath();
        ctx.moveTo(xCenter - axW/2, arrowCy - axH/2);
        ctx.lineTo(xCenter + axW/2 - aHeadW, arrowCy - axH/2);
        ctx.lineTo(xCenter + axW/2 - aHeadW, arrowCy - aHeadH/2);
        ctx.lineTo(xCenter + axW/2, arrowCy);
        ctx.lineTo(xCenter + axW/2 - aHeadW, arrowCy + aHeadH/2);
        ctx.lineTo(xCenter + axW/2 - aHeadW, arrowCy + axH/2);
        ctx.lineTo(xCenter - axW/2, arrowCy + axH/2);
        ctx.closePath();
        ctx.fill();
    },
    afterDraw: (chart) => {
        const ctx = chart.ctx;
        const xAxis = chart.scales.x;
        const yAxis = chart.scales.y;
        const chartArea = chart.chartArea;

        // 1. Bond length short dashed line & label (stops above text)
        const minPx = xAxis.getPixelForValue(74);
        const minPy = yAxis.getPixelForValue(-4.5);

        ctx.beginPath();
        ctx.setLineDash([4, 4]);
        ctx.moveTo(minPx, minPy);
        ctx.lineTo(minPx, minPy + 25);
        ctx.strokeStyle = '#555';
        ctx.lineWidth = 1;
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.fillStyle = '#278e58';
        ctx.font = '14px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        ctx.fillText('74 pm', minPx, minPy + 30); // Positioned directly below dashed line

        // Bond length annotation (arrow points EXACTLY to dashed line from the right)
        const arrowY = minPy + 20;
        const arrowEndX = minPx + 6; 
        const arrowStartX = minPx + 40;

        ctx.beginPath();
        ctx.moveTo(arrowStartX, arrowY);
        ctx.lineTo(arrowEndX, arrowY);
        ctx.strokeStyle = '#278e58';
        ctx.lineWidth = 1.2;
        ctx.stroke();

        // Arrowhead pointing left
        ctx.beginPath();
        ctx.moveTo(arrowEndX, arrowY);
        ctx.lineTo(arrowEndX + 6, arrowY - 4);
        ctx.lineTo(arrowEndX + 6, arrowY + 4);
        ctx.closePath();
        ctx.fillStyle = '#278e58';
        ctx.fill();

        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText('Bond length', arrowStartX + 4, arrowY);

        // 2. Static Region Labels (No static spheres drawn, to avoid duplicate visuals)
        ctx.font = '14px sans-serif';
        ctx.textAlign = 'center';

        ctx.fillStyle = '#378b8e';
        ctx.textBaseline = 'top';
        ctx.fillText('HH (too close)', xAxis.getPixelForValue(48), chartArea.top + 10);

        ctx.fillStyle = '#278e58';
        ctx.textBaseline = 'bottom';
        ctx.fillText('H—H', xAxis.getPixelForValue(74), minPy - 10);

        const yZero = yAxis.getPixelForValue(0);
        ctx.fillStyle = '#c5337b';
        ctx.textBaseline = 'bottom';
        ctx.fillText('H - - - H (too far)', xAxis.getPixelForValue(150), yZero - 10);

        // 3. Dynamic Locators (One unified pair of atoms tracking the slider)
        const curPx = xAxis.getPixelForValue(currentDistance);
        const curEnergy = 4.5 * Math.pow(1 - Math.exp(-0.035 * (currentDistance - 74)), 2) - 4.5;

        if (curEnergy <= 22) { // Render only if within sensible view bounds
            const curPy = yAxis.getPixelForValue(curEnergy);

            // Magenta locator dot on curve
            ctx.fillStyle = '#d31f7c';
            ctx.beginPath();
            ctx.arc(curPx, curPy, 6, 0, 2*Math.PI);
            ctx.fill();
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1.5;
            ctx.stroke();

            // Dynamic tracking spheres 
            const R = 11;
            // Physical atomic distance map (spheres exactly touch at 74pm distance)
            const curVd = (currentDistance / 74) * 22; 

            // Constrain dynamic spheres vertically to sit nicely near curve without going off bounds
            // or colliding with top/bottom text regions.
            let baseSphereY = curPy - 40;
            if (baseSphereY < chartArea.top + 40) baseSphereY = chartArea.top + 40;
            if (baseSphereY > chartArea.bottom - 40) baseSphereY = chartArea.bottom - 40;

            drawSphere(ctx, curPx - curVd/2, baseSphereY, R);
            drawSphere(ctx, curPx + curVd/2, baseSphereY, R);
        }
    }
};

window.myChart = new Chart(canvas, {
    type: 'line',
    data: {
        datasets: [{
            data: energyData,
            borderColor: '#db1f79',
            borderWidth: 3,
            fill: false,
            pointRadius: 0,
            tension: 0.1
        }]
    },
    options: {
        responsive: true,
        maintainAspectRatio: false,
        layout: { 
            // Adjusted padding to allow space for the bottom x-axis elements and left ticks
            padding: { left: 80, bottom: 85, top: 25, right: 35 } 
        },
        scales: {
            x: { type: 'linear', min: 25, max: 210, display: false },
            y: { type: 'linear', min: -8, max: 20, display: false }
        },
        plugins: { 
            legend: { display: false }, 
            tooltip: { enabled: false } 
        },
        animation: { duration: 0 } 
    },
    plugins: [customPlugin]
});

canvas.addEventListener('click', (e) => {
    const rect = canvas.getBoundingClientRect();
    const clickX = e.clientX - rect.left;
    const chartArea = window.myChart.chartArea;

    if(clickX >= chartArea.left && clickX <= chartArea.right) {
        const rVal = window.myChart.scales.x.getValueForPixel(clickX);
        let targetDist;

        if(rVal < 60) {
            targetDist = 40;
            showPopup('Nuclear Repulsion', 'When forced closer than the bond length, the positively charged nuclei strongly repel each other, causing a rapid spike in potential energy.');
        } else if(rVal <= 100) {
            targetDist = 74;
            showPopup('Optimal Bond Length', 'At 74 pm, the attractive and repulsive forces balance perfectly. The system settles into its most stable, lowest-energy state as a covalent bond.');
        } else {
            targetDist = 160;
            showPopup('Separated Atoms', 'At large distances, the atoms barely interact and their potential energy approaches zero.');
        }

        document.getElementById('distanceInput').value = targetDist;
        document.getElementById('distanceVal').value = targetDist;
        update_distance(targetDist);
    }
});

canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const clickX = e.clientX - rect.left;
    const clickY = e.clientY - rect.top;
    const chartArea = window.myChart.chartArea;

    if(clickX >= chartArea.left && clickX <= chartArea.right && clickY >= chartArea.top && clickY <= chartArea.bottom) {
        canvas.style.cursor = 'pointer';
        const rVal = window.myChart.scales.x.getValueForPixel(clickX);
        if(rVal < 60) showTooltip('Repulsive region (Click)', e);
        else if(rVal <= 100) showTooltip('Bonding region (Click)', e);
        else showTooltip('Separated region (Click)', e);
    } else {
        canvas.style.cursor = 'default';
        hideTooltip();
    }
});

canvas.addEventListener('mouseout', hideTooltip);

window.update_distance = function(val) {
    currentDistance = val;
    window.myChart.update();
    hidePopup();
}

const steps = [
    {
      title: "Separated atoms",
      narration: "When two hydrogen atoms are far apart, they barely interact. Their potential energy is near zero.",
      state: { distance: 200 }
    },
    {
      title: "Optimal bond length",
      narration: "As they move closer, attractive forces lower the potential energy until it hits a minimum at 74 pm. This most stable point is the covalent bond length.",
      state: { distance: 74 }
    },
    {
      title: "Nuclear repulsion",
      narration: "If forced closer than the bond length, the positively charged nuclei strongly repel each other, causing the potential energy to spike rapidly.",
      state: { distance: 40 }
    }
];
let currentStep = 0;

function renderStep() {
    if(!document.getElementById('demoNarration')) return;
    const step = steps[currentStep];

    document.getElementById('demoNarration').innerText = step.narration;
    document.getElementById('stepLabel').innerText = (currentStep + 1) + " / " + steps.length;
    document.getElementById('btnPrev').disabled = (currentStep === 0);
    document.getElementById('btnNext').disabled = (currentStep === steps.length - 1);

    for(let key in step.state) {
        const val = step.state[key];
        const input = document.getElementById(key + 'Input');
        if(input) {
            input.value = val;
            const output = document.getElementById(key + 'Val');
            if(output) output.value = val;
            if(window['update_' + key]) window['update_' + key](val);
        }
    }
}

window.prevStep = function() { if(currentStep > 0) { currentStep--; renderStep(); } };
window.nextStep = function() { if(currentStep < steps.length - 1) { currentStep++; renderStep(); } };

setTimeout(renderStep, 0);
window.__markRendered();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

